import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="3mo",progress=False,auto_adjust=True); close=data["Close"]; volume=data["Volume"]; print("\n".join((lambda p,p5,mm20,rvol,s,signal:f"{t}: {p:.2f} | Var 5j: {p5:+.2f}% | MM20: {mm20:.2f} | RVOL: {rvol:.2f} | Score: {s}/100 | Signal: {signal}")(float(close[t].dropna().iloc[-2]),(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100,float(close[t].dropna().iloc[-21:-1].mean()),float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean()),(40 if float(close[t].dropna().iloc[-2])>float(close[t].dropna().iloc[-21:-1].mean()) else 0)+(30 if 3<(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100<8 else 0)+(30 if float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean())>=1.5 else 0),("SURCHAUFFE" if (float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100>=8 else "ACHAT" if ((40 if float(close[t].dropna().iloc[-2])>float(close[t].dropna().iloc[-21:-1].mean()) else 0)+(30 if 3<(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100<8 else 0)+(30 if float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean())>=1.5 else 0))>=70 else "SURVEILLANCE" if ((40 if float(close[t].dropna().iloc[-2])>float(close[t].dropna().iloc[-21:-1].mean()) else 0)+(30 if 3<(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100<8 else 0)+(30 if float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean())>=1.5 else 0))>=40 else "AUCUN SIGNAL")) for t in tickers if t in close.columns and close[t].dropna().shape[0]>=21))
